test('fresh double active review refreshes both actors and continues battle',async()=>{const {activeLeadAliasFixture}=await import('./fixtures/active-lead-alias.mjs'),{createClassicCombat}=await import('../lib/rogue-battle-engine.mjs'),{makeReferenceMon}=await import('../lib/rogue-reference.mjs'),{classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs'),{applyClassicAction}=await import('../lib/rogue-classic-game.mjs');for(const targetSlot of [0,1]){let doc=activeLeadAliasFixture({kind:'trainer'}),run=doc.classic.slots[0];if(targetSlot===1)run.party.reverse();run.combat=createClassicCombat(run,[makeReferenceMon(143,30,{boxId:'foe',moves:['Splash']}),makeReferenceMon(129,30,{boxId:'foe2',moves:['Splash']})],{trainer:true,doubles:true});run.party=run.combat.teams[0];const before=structuredClone(run),preview=classicMoveAliasPreview(run,'one');assert.ok(preview,`slot ${targetSlot}`);applyClassicAction(doc,{action:'repairMoveAliases',boxId:'one',confirm:true,expectedMoves:preview.moves});assert.deepEqual(run.combat.activeBySide,before.combat.activeBySide);assert.deepEqual(run.combat.requests[0].actors[targetSlot].moves.map(m=>m.id),['tackle','growl']);assert.deepEqual(run.combat.requests[0].actors[1-targetSlot],before.combat.requests[0].actors[1-targetSlot]);assert.deepEqual(run.combat.snapshot.prng,before.combat.snapshot.prng);assert.deepEqual(run.combat.snapshot.field,before.combat.snapshot.field);assert.deepEqual(run.party[1-targetSlot],before.party[1-targetSlot]);doc=JSON.parse(JSON.stringify(doc));run=doc.classic.slots[0];const actions=[0,1].map(actor=>{const move=actor===targetSlot?'tackle':'splash',entry=run.combat.requests[0].actors[actor].moves.find(m=>m.id===move);return {actor,type:'move',move,...(entry.targets.length?{target:entry.targets[0].target}:{})};});applyClassicAction(doc,{action:'turn',command:{type:'turn',actions}});assert.ok(run.combat.snapshot.turn>before.combat.snapshot.turn||run.combat.ended);assert.deepEqual(doc.classic.slots[1],{id:'other'});}});

