test('later double battle review refuses inconsistent partner or selected history',async()=>{const {activeLeadAliasFixture}=await import('./fixtures/active-lead-alias.mjs'),{createClassicCombat}=await import('../lib/rogue-battle-engine.mjs'),{makeReferenceMon}=await import('../lib/rogue-reference.mjs'),{classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs'),{applyClassicAction}=await import('../lib/rogue-classic-game.mjs');for(const mutate of [r=>r.combat.requests[0].actors[1].active=0,r=>r.combat.snapshot.sides[0].active[1]='[Pokemon:p1a]',r=>r.combat.snapshot.sides[0].pokemon[0].moveSlots[0].used=true,r=>r.combat.snapshot.sides[0].pokemon[0].activeTurns=1,r=>r.combat.snapshot.sides[0].choice.actions.push({choice:'move'})]){const doc=activeLeadAliasFixture({kind:'trainer'}),run=doc.classic.slots[0];run.combat=createClassicCombat(run,[makeReferenceMon(143,30,{boxId:'foe',moves:['Splash']}),makeReferenceMon(129,30,{boxId:'foe2',moves:['Splash']})],{trainer:true,doubles:true});run.party=run.combat.teams[0];applyClassicAction(doc,{action:'turn',command:{type:'turn',actions:[{actor:0,type:'move',move:'growl'},{actor:1,type:'move',move:'splash'}]}});mutate(run);const before=structuredClone(run);assert.equal(classicMoveAliasPreview(run,'one'),null);assert.deepEqual(run,before);}});

test('later active randomized fusion and Sketch review preserves history and donor',async()=>{const {randomizedFusionAliasFixture}=await import('./fixtures/randomized-fusion-alias.mjs'),{classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs'),{validatedClassicDnaFusion,previewClassicDnaUnsplice}=await import('../lib/rogue-dna-fusion.mjs'),{applyClassicAction}=await import('../lib/rogue-classic-game.mjs');for(const sketch of [false,true]){const f=randomizedFusionAliasFixture({active:true,leadActive:true,abilityRandom:true,sketch,extraMove:true});let doc=JSON.parse(JSON.stringify(f.doc)),run=doc.classic.slots[0];applyClassicAction(doc,{action:'turn',command:{type:'move',move:'splash'}});assert.equal(run.combat.snapshot.turn,2);const before=structuredClone(run),preview=classicMoveAliasPreview(run,'one');assert.ok(preview,`sketch ${sketch}`);applyClassicAction(doc,{action:'repairMoveAliases',boxId:'one',confirm:true,expectedMoves:preview.moves,...(sketch?{removeIndex:2,expectedSketchPP:preview.sketchPP}:{})});const native=run.combat.snapshot.sides[0].pokemon[0];assert.deepEqual(native.lastMove,before.combat.snapshot.sides[0].pokemon[0].lastMove);assert.equal(native.moveSlots.at(-1).used,true);assert.ok(validatedClassicDnaFusion(run.party[0]));assert.deepEqual(run.party[0].rogueFusion.donor,before.party[0].rogueFusion.donor);assert.deepEqual(previewClassicDnaUnsplice(run.party[0]).primary.moves,run.party[0].moves);if(sketch)assert.deepEqual(run.party[0].rogueSketchPP,[2,1,19]);assert.deepEqual(run.combat.snapshot.prng,before.combat.snapshot.prng);doc=JSON.parse(JSON.stringify(doc));run=doc.classic.slots[0];applyClassicAction(doc,{action:'turn',command:{type:'move',move:f.key}});assert.ok(run.combat.snapshot.turn>2||run.combat.ended);assert.deepEqual(doc.classic.slots[1],{id:'other'});}});

test('later active fusion Sketch review rejects inconsistent history or donor',async()=>{const {randomizedFusionAliasFixture}=await import('./fixtures/randomized-fusion-alias.mjs'),{classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs'),{applyClassicAction}=await import('../lib/rogue-classic-game.mjs');for(const mutate of [r=>r.party[0].rogueFusion.donor.rogueMovesetSeed='wrong',r=>r.party[0].rogueSketchPP[2]--,r=>r.combat.teams[0][0].rogueSketchPP[2]--,r=>r.combat.snapshot.sides[0].pokemon[0].moveSlots[2].pp--,r=>r.combat.snapshot.sides[0].pokemon[0].moveSlots[0].used=true,r=>r.combat.snapshot.sides[0].pokemon[0].activeTurns=1,r=>r.combat.snapshot.sides[0].pokemon[0].transformed=true]){const {doc}=randomizedFusionAliasFixture({active:true,leadActive:true,abilityRandom:true,sketch:true,extraMove:true}),run=doc.classic.slots[0];applyClassicAction(doc,{action:'turn',command:{type:'move',move:'splash'}});mutate(run);const before=structuredClone(run);assert.equal(classicMoveAliasPreview(run,'one'),null);assert.deepEqual(run,before);}});

test('later active wild event review preserves event progress and move history',async()=>{const {classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs'),{applyClassicAction}=await import('../lib/rogue-classic-game.mjs');for(const type of ['berries','fight-or-flight']){let doc=wildEventReviewFixture(type,{activeSlot:0}),run=doc.classic.slots[0];applyClassicAction(doc,{action:'turn',command:{type:'move',move:'growl'}});assert.equal(run.combat.snapshot.turn,2,type);const before=structuredClone(run),preview=classicMoveAliasPreview(run,'one');assert.ok(preview,type);applyClassicAction(doc,{action:'repairMoveAliases',boxId:'one',confirm:true,expectedMoves:preview.moves});const native=run.combat.snapshot.sides[0].pokemon[0];assert.deepEqual(native.moveSlots.map(s=>[s.id,s.used]),[['tackle',false],['growl',true]]);assert.deepEqual(native.lastMove,before.combat.snapshot.sides[0].pokemon[0].lastMove);assert.deepEqual(run.combat.snapshot.field,before.combat.snapshot.field);assert.deepEqual(run.combat.snapshot.prng,before.combat.snapshot.prng);assert.deepEqual(run.mystery,before.mystery);doc=JSON.parse(JSON.stringify(doc));run=doc.classic.slots[0];applyClassicAction(doc,{action:'turn',command:{type:'move',move:'tackle'}});assert.ok(run.combat.snapshot.turn>2||run.combat.ended||run.combat.snapshot.requestState==='switch');assert.deepEqual(doc.classic.slots[1],{id:'other',safe:true});}});

